//! Definitions of page mapping properties.
//!
//! The flag types are hand-rolled rather than generated by the `bitflags`
//! crate, so that vOSTD has no dependency beyond `core` and `alloc`. The bit
//! values, names and the `bits`/`contains` methods are those of real OSTD.

/// The property of a mapped virtual memory page.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct PageProperty {
    /// The flags associated with the page.
    pub flags: PageFlags,
    /// The cache policy for the page.
    pub cache: CachePolicy,
    pub(crate) priv_flags: PrivilegedPageFlags,
}

impl PageProperty {
    /// Creates a new `PageProperty` with the given flags and cache policy for
    /// the user.
    pub fn new_user(flags: PageFlags, cache: CachePolicy) -> Self {
        Self {
            flags,
            cache,
            priv_flags: PrivilegedPageFlags::USER,
        }
    }
}

/// A type to control the cacheability of the main memory.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum CachePolicy {
    /// Uncacheable (UC).
    Uncacheable,
    /// Write-Combining (WC).
    WriteCombining,
    /// Write-Protect (WP).
    WriteProtected,
    /// Writethrough (WT).
    Writethrough,
    /// Writeback (WB). The "normal" memory.
    Writeback,
}

macro_rules! flags {
    ($(#[$meta:meta])* $vis:vis struct $name:ident: $ty:ty { $( $(#[$fmeta:meta])* const $flag:ident = $value:expr; )* }) => {
        $(#[$meta])*
        #[derive(Clone, Copy, Debug, Eq, PartialEq)]
        $vis struct $name($ty);

        #[allow(dead_code)]
        impl $name {
            $( $(#[$fmeta])* pub const $flag: Self = Self($value); )*

            /// An empty set of flags.
            pub const fn empty() -> Self {
                Self(0)
            }

            /// The raw bits.
            pub const fn bits(&self) -> $ty {
                self.0
            }

            /// Whether all the flags in `other` are set.
            pub const fn contains(&self, other: Self) -> bool {
                self.0 & other.0 == other.0
            }
        }

        impl core::ops::BitOr for $name {
            type Output = Self;
            fn bitor(self, rhs: Self) -> Self {
                Self(self.0 | rhs.0)
            }
        }

        impl core::ops::BitAnd for $name {
            type Output = Self;
            fn bitand(self, rhs: Self) -> Self {
                Self(self.0 & rhs.0)
            }
        }

        impl core::ops::Sub for $name {
            type Output = Self;
            fn sub(self, rhs: Self) -> Self {
                Self(self.0 & !rhs.0)
            }
        }

        impl core::ops::SubAssign for $name {
            fn sub_assign(&mut self, rhs: Self) {
                self.0 &= !rhs.0;
            }
        }

        impl core::ops::BitOrAssign for $name {
            fn bitor_assign(&mut self, rhs: Self) {
                self.0 |= rhs.0;
            }
        }
    };
}

flags! {
    /// Page protection permissions and access status.
    pub struct PageFlags: u8 {
        /// Readable.
        const R = 0b00000001;
        /// Writable.
        const W = 0b00000010;
        /// Executable.
        const X = 0b00000100;
        /// Readable + writable.
        const RW = 0b00000011;
        /// Readable + executable.
        const RX = 0b00000101;
        /// Readable + writable + executable.
        const RWX = 0b00000111;
        /// Has the memory page been read or written.
        const ACCESSED = 0b00001000;
        /// Has the memory page been written.
        const DIRTY = 0b00010000;
        /// The second bit available for software use.
        const AVAIL2 = 0b10000000;
    }
}

flags! {
    /// Page property that are only accessible in OSTD.
    pub(crate) struct PrivilegedPageFlags: u8 {
        /// Accessible from user mode.
        const USER = 0b00000001;
        /// Global page that won't be evicted from TLB with normal TLB flush.
        const GLOBAL = 0b00000010;
        /// Reserved for OSTD.
        const AVAIL1 = 0b01000000;
    }
}
